def is_3_colorable(graph_edges):
    n = 19
    adj = [set() for _ in range(n)]
    for u,v in graph_edges:
        adj[u].add(v)
        adj[v].add(u)
    colors = [-1]*n

    def backtrack(v):
        if v == n:
            return True
        if colors[v] != -1:
            return backtrack(v+1)
        for c in range(3):
            ok = True
            for u in adj[v]:
                if colors[u] == c:
                    ok = False
                    break
            if ok:
                colors[v] = c
                if backtrack(v+1):
                    return True
                colors[v] = -1
        return False

    # Order vertices by degree (highest first) for efficiency
    degrees = [len(adj[i]) for i in range(n)]
    order = sorted(range(n), key=lambda x: -degrees[x])
    pos = {v:i for i,v in enumerate(order)}

    colors = [-1]*n
    def backtrack2(idx):
        if idx == n:
            return True
        v = order[idx]
        for c in range(3):
            ok = True
            for u in adj[v]:
                if pos[u] < idx and colors[u] == c:
                    ok = False
                    break
            if ok:
                colors[v] = c
                if backtrack2(idx+1):
                    return True
                colors[v] = -1
        return False

    return backtrack2(0)

# Test
print(is_3_colorable([(0,1),(1,2),(2,0)]))  # K3, not 3-colorable? Actually it is 3-colorable
print(is_3_colorable([(0,1),(1,2),(2,0),(0,2)]))  # triangle, 3-colorable
print(is_3_colorable([(0,1),(1,2),(2,3),(3,0),(0,2),(1,3)]))  # K4, not 3-colorable

