def find_short_cycles(graph_edges, max_len=7):
    """Find all cycles of length at most max_len in the graph."""
    adj = [set() for _ in range(n)]
    for u,v in graph_edges:
        adj[u].add(v)
        adj[v].add(u)

    cycles = []

    # For each possible starting vertex
    for start in range(n):
        # Use DFS with depth limit
        def dfs(v, path, visited):
            if len(path) > max_len:
                return
            for w in adj[v]:
                if w == start and len(path) >= 3 and len(path) <= max_len:
                    # Found a cycle
                    cycle = tuple(path)
                    # Canonical form
                    min_idx = cycle.index(min(cycle))
                    rot = cycle[min_idx:] + cycle[:min_idx]
                    rev = tuple(reversed(cycle))
                    min_idx_rev = rev.index(min(rev))
                    rot_rev = rev[min_idx_rev:] + rev[:min_idx_rev]
                    canon = min(rot, rot_rev)
                    cycles.append(canon)
                elif w not in visited and len(path) < max_len:
                    # To avoid duplicates, require w > path[0] for non-start vertices
                    if w > path[0] or w == start:
                        dfs(w, path + [w], visited | {w})

        for neighbor in adj[start]:
            if neighbor > start:  # Avoid duplicate cycles
                dfs(neighbor, [start, neighbor], {start, neighbor})

    return list(set(cycles))

