import random

n = 19
min_edges = 37

# Edge variables
edges = {}
for i in range(n):
    for j in range(i+1, n):
        edges[(i,j)] = Bool(f'e_{i}_{j}')

# Color variables: color[v] in {0,1,2}
colors = {}
for v in range(n):
    colors[v] = Int(f'c_{v}')

def find_short_cycles(graph_edges, max_len=7):
    """Find all cycles of length at most max_len in the graph."""
    adj = [set() for _ in range(n)]
    for u,v in graph_edges:
        adj[u].add(v)
        adj[v].add(u)

    cycles = []

    for start in range(n):
        def dfs(v, path, visited):
            if len(path) > max_len:
                return
            for w in adj[v]:
                if w == start and len(path) >= 3 and len(path) <= max_len:
                    cycle = tuple(path)
                    min_idx = cycle.index(min(cycle))
                    rot = cycle[min_idx:] + cycle[:min_idx]
                    rev = tuple(reversed(cycle))
                    min_idx_rev = rev.index(min(rev))
                    rot_rev = rev[min_idx_rev:] + rev[:min_idx_rev]
                    canon = min(rot, rot_rev)
                    cycles.append(canon)
                elif w not in visited and len(path) < max_len:
                    if w > path[0] or w == start:
                        dfs(w, path + [w], visited | {w})

        for neighbor in adj[start]:
            if neighbor > start:
                dfs(neighbor, [start, neighbor], {start, neighbor})

    return list(set(cycles))

def solve_with_forbidden_cycles(forbidden_cycles):
    s = Solver()

    # Edge count >= 37
    edge_vars = list(edges.values())
    s.add(PbGe([(e,1) for e in edge_vars], min_edges))

    # Coloring constraints
    for v in range(n):
        s.add(colors[v] >= 0, colors[v] <= 2)

    for i in range(n):
        for j in range(i+1, n):
            s.add(Or(Not(edges[(i,j)]), colors[i] != colors[j]))

    # Forbid specific cycles
    for cycle in forbidden_cycles:
        cycle_edges = []
        for k in range(len(cycle)):
            u, v = cycle[k], cycle[(k+1)%len(cycle)]
            if u > v:
                u, v = v, u
            cycle_edges.append(Not(edges[(u,v)]))
        s.add(Or(cycle_edges))

    if s.check() == sat:
        m = s.model()
        graph_edges = []
        for i in range(n):
            for j in range(i+1, n):
                if is_true(m[edges[(i,j)]]):
                    graph_edges.append((i,j))
        coloring = [m[colors[v]].as_long() for v in range(n)]
        return graph_edges, coloring
    else:
        return None, None

# Iterative approach
forbidden = []
max_iters = 50

for iteration in range(max_iters):
    print(f"Iteration {iteration}, forbidden cycles: {len(forbidden)}")
    result = solve_with_forbidden_cycles(forbidden)

    if result[0] is None:
        print("UNSAT - no graph exists with these constraints")
        break

    graph_edges, coloring = result
    print(f"Found graph with {len(graph_edges)} edges")

    # Find short cycles
    short_cycles = find_short_cycles(graph_edges, 7)
    print(f"Short cycles found: {len(short_cycles)}")

    if len(short_cycles) == 0:
        print("SUCCESS! No short cycles found.")
        print(f"Graph edges: {graph_edges}")
        print(f"Coloring: {coloring}")
        break

    # Add all short cycles to forbidden list
    for c in short_cycles:
        if c not in forbidden:
            forbidden.append(c)

    print(f"Added {len(short_cycles)} new forbidden cycles")
    print(f"Sample cycles: {short_cycles[:5]}")
    print()
else:
    print("Max iterations reached")
